SELECT * FROM memory_change
WHERE tenant_id = #{tenantId} AND store_id = #{storeId}
  AND idempotency_key = #{idempotencyKey} LIMIT 1

SELECT * FROM memory_change
WHERE tenant_id = #{tenantId} AND store_id = #{storeId}
  AND store_revision > #{afterRevision}
ORDER BY store_revision ASC LIMIT #{limit}
